// HasDeveloper applies the HasEdge predicate on the "developer" edge.
func HasDeveloper() predicate.BundlePayouts {
	return predicate.BundlePayouts(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DeveloperTable, DeveloperColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDeveloperWith applies the HasEdge predicate on the "developer" edge with a given conditions (other predicates).
func HasDeveloperWith(preds ...predicate.User) predicate.BundlePayouts {
	return predicate.BundlePayouts(func(s *sql.Selector) {
		step := newDeveloperStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundlePayouts) predicate.BundlePayouts {
	return predicate.BundlePayouts(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundlePayouts) predicate.BundlePayouts {
	return predicate.BundlePayouts(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundlePayouts) predicate.BundlePayouts {
	return predicate.BundlePayouts(sql.NotPredicates(p))
}
